import React, { Component } from "react";
import { texts } from './texts';
import TableRow from './components/TableRow/';
import FormSelect from './components/FormSelect';
import AboutModal from './components/AboutModal';
import SearchBar from './components/SearchBar';
import Footer from './components/Footer';
import './App.css';

class App extends Component {

  state = {
    texts: null,
    backupTexts: null, // To keep a fresh copy at all times. Used for filtering
    sortByOption: "year",
    sortDirection: "asc",
    typesDisplayed: ["Annotation", "Prose", "Letter", "Blurb", "Diary", "Poem"],
    searchTerm: '',
    searchField: 'all',
  };

  componentDidMount() {
    this.formatTexts();
  };

  hideLoadingSpinner() {
    const spinner = document.getElementById('loading-spinner');
    if (spinner) {
      // Wait for fonts to load before hiding spinner to prevent FOUT
      if (document.fonts && document.fonts.ready) {
        document.fonts.ready.then(() => {
          spinner.classList.add('hidden');
        });
      } else {
        // Fallback for browsers without font loading API
        spinner.classList.add('hidden');
      }
    }
  }

  formatTexts() {
    // Get fresh copy of texts from import (that's the only time they need to be formatted)
    let textsCopy = texts;
    // Format data properly
    let formattedTexts = [];
    for (let i = 0; i < textsCopy.length; i++) {
      let formattedText = {};
      formattedText.year = textsCopy[i].year;
      formattedText.type = textsCopy[i].type;
      formattedText.title = textsCopy[i].title;
      formattedText.id = textsCopy[i].id; // stable unique id — used for the modal id (see Modal)
      if (texts[i].printedIn) {
        formattedText.reference = textsCopy[i].printedIn
      }
      if (texts[i].issueOrVolume) {
        if (texts[i].monthAndDay) {
          formattedText.reference += ", " + textsCopy[i].issueOrVolume;
          formattedText.reference += " (" + textsCopy[i].monthAndDay + ")";
        } else {
          formattedText.reference += ", " + textsCopy[i].issueOrVolume;
        }
      }
      if (!texts[i].issueOrVolume && texts[i].monthAndDay) {
        formattedText.reference += " (" + textsCopy[i].monthAndDay + ")";
      }
      if (texts[i].pageRange) {
        formattedText.reference += ", " + textsCopy[i].pageRange;
      }
      if (texts[i].textProvided !== false) {
        formattedText.textProvided = textsCopy[i].textProvided;
      } else {
        formattedText.textProvided = false
      }
      if (texts[i].notes !== null) {
        // Separate inline footnotes ("[N] ...") from bibliographic notes. A footnote
        // that matches a <sup>N</sup> marker in the text is attached as a hover tooltip
        // on that marker (so a long footnote list — e.g. the Radio Talks' 24 — no longer
        // overflows the notes tooltip); any unmatched note stays in the notes list below.
        const rawNotes = textsCopy[i].notes;
        const footnoteMap = {};
        for (let j = 0; j < rawNotes.length; j++) {
          const m = rawNotes[j].match(/^\[(\d+)\]\s*([\s\S]*)$/);
          if (m) { footnoteMap[m[1]] = m[2]; }
        }
        const usedFootnotes = {};
        if (typeof formattedText.textProvided === 'string' && Object.keys(footnoteMap).length) {
          formattedText.textProvided = formattedText.textProvided.replace(/<sup>(\d+)<\/sup>/g, (full, n) => {
            if (footnoteMap[n] != null) {
              usedFootnotes[n] = true;
              const plain = footnoteMap[n].replace(/<[^>]*>/g, '').replace(/&/g, '&amp;').replace(/"/g, '&quot;');
              return '<sup class="footnote-ref" title="' + plain + '">' + n + '</sup>';
            }
            return full;
          });
        }
        // Notes still shown in the tooltip/list: bibliographic notes plus any footnote
        // that had no matching <sup> marker in the text.
        const displayNotes = rawNotes.filter((note) => {
          const m = note.match(/^\[(\d+)\]/);
          return !(m && usedFootnotes[m[1]]);
        });

        if (displayNotes.length) {
          // Expected input is html, since the tooltip the data will be passed to can accept html
          formattedText.tooltipNotes = "<ul class='left-align' style='padding-left: 15px; padding-right: 15px; font-size: .9rem'>";
          for (let j = 0; j < displayNotes.length; j++) {
              formattedText.tooltipNotes += "<li>" + displayNotes[j] + "</li>";
              if (j !== (displayNotes.length - 1)) {
                formattedText.tooltipNotes += "<br>";
              }
          }
          formattedText.tooltipNotes += "</ul>";

          // But I also need notes in non-tooltip form for tablet and mobile
          formattedText.notes = "<ul class='left-align' style='font-size: .9rem; padding-left: 15px; padding-right: 5px;'>";
          for (let j = 0; j < displayNotes.length; j++) {
              formattedText.notes += "<li style='list-style-type: square;'>" + displayNotes[j] + "</li>";
              if (j !== (displayNotes.length - 1)) {
                formattedText.notes += "<br>";
              }
          }
          formattedText.notes += "</ul>";
        } else {
          formattedText.notes = null;
          formattedText.tooltipNotes = null;
        }
      } else {
        formattedText.notes = null;
        formattedText.tooltipNotes = null;
      }
      formattedTexts.push(formattedText);
    }
    // Replace current state with newly formatted texts array
    this.setState({
      texts: formattedTexts,
      backupTexts: formattedTexts
    }, () => {
      this.sort("year"); // Set standard sorting option
      this.hideLoadingSpinner();
    });
  };

  updateSortOption = (option) => {
    this.setState({
      sortByOption: option,
      sortDirection: "asc"
    }, () => {
      this.sort(option);
    })
  }

  handleHeaderSort = (column) => {
    const option = column.toLowerCase();
    if (this.state.sortByOption === option) {
      // Toggle direction if same column
      const newDirection = this.state.sortDirection === "asc" ? "desc" : "asc";
      this.setState({ sortDirection: newDirection }, () => {
        this.sort(option);
      });
    } else {
      // New column, default to ascending
      this.setState({ sortByOption: option, sortDirection: "asc" }, () => {
        this.sort(option);
      });
    }
  }

  renderSortIndicator = (column) => {
    const option = column.toLowerCase();
    if (this.state.sortByOption !== option) {
      return null;
    }
    // SVG triangle matching Materialize's caret style
    const isAsc = this.state.sortDirection === "asc";
    return (
      <svg className="sort-indicator" height="24" viewBox="0 0 24 24" width="24" style={{transform: isAsc ? 'rotate(180deg)' : 'none'}}>
        <path fill="rgba(0,0,0,0.87)" d="M7 10l5 5 5-5z"/>
      </svg>
    );
  }

  // CHANGE 4A: Extracted comparator logic into reusable method
  // Previously, sorting logic was inline in sort() and couldn't be reused.
  // Now we can use the same comparator for both texts and backupTexts.
  getComparator(option) {
    // Without this function all titles and references which begin with an html <i> tag will be sorted before other non-italicized strings
    function ignoreItalicTag(string) {
      if (string.startsWith("<i>")) {
        return string.slice(3);
      } else {
        return string;
      }
    }

    if (option === "year") {
      return function (a, b) {
        // If years match, then sort by title instead
        if (a["year"] === b["year"]) {
          // If titles match, then sort by reference instead
          if (ignoreItalicTag(a["title"]) === ignoreItalicTag(b["title"])) {
            return ignoreItalicTag(a["reference"]).localeCompare(ignoreItalicTag(b["reference"]), undefined, {ignorePunctuation: true});
          }
          return ignoreItalicTag(a["title"]).localeCompare(ignoreItalicTag(b["title"]), undefined, {ignorePunctuation: true});
        }
        return a["year"] > b["year"] ? 1 : -1;
      };
    }

    if (option === "title") {
      return function (a, b) {
        if (a["title"] === b["title"]) {
          if (a["year"] === b["year"]) {
            return ignoreItalicTag(a["reference"]).localeCompare(ignoreItalicTag(b["reference"]), undefined, {ignorePunctuation: true});
          }
          return a["year"] > b["year"] ? 1 : -1;
        }
        return ignoreItalicTag(a["title"]).localeCompare(ignoreItalicTag(b["title"]), undefined, {ignorePunctuation: true});
      };
    }

    if (option === "reference") {
      return function (a, b) {
        if (ignoreItalicTag(a["reference"]) === ignoreItalicTag(b["reference"])) {
          return ignoreItalicTag(a["title"]).localeCompare(ignoreItalicTag(b["title"]), undefined, {ignorePunctuation: true});
        }
        return ignoreItalicTag(a["reference"]) > ignoreItalicTag(b["reference"]) ? 1 : -1;
      };
    }

    if (option === "type") {
      return function (a, b) {
        if (a["type"] === b["type"]) {
          if (a["year"] === b["year"]) {
            if (ignoreItalicTag(a["title"]) === ignoreItalicTag(b["title"])) {
              return ignoreItalicTag(a["reference"]).localeCompare(ignoreItalicTag(b["reference"]), undefined, {ignorePunctuation: true});
            }
            return ignoreItalicTag(a["title"]).localeCompare(ignoreItalicTag(b["title"]), undefined, {ignorePunctuation: true});
          }
          return a["year"] > b["year"] ? 1 : -1;
        }
        return a["type"].localeCompare(b["type"], undefined, {ignorePunctuation: true});
      };
    }
  }

  // CHANGE 4B: Sort both texts AND backupTexts
  // Previously, only texts was sorted, leaving backupTexts unsorted.
  // This meant every filter operation required re-sorting after filtering.
  // Now backupTexts stays sorted, so filtering preserves sort order automatically.
  sort(option) {
    const baseComparator = this.getComparator(option);
    const direction = this.state.sortDirection;

    // Wrap comparator to handle descending order
    const comparator = direction === "desc"
      ? (a, b) => -baseComparator(a, b)
      : baseComparator;

    // Use spread operator to create new arrays (avoids mutating state directly)
    const sortedTexts = [...this.state.texts].sort(comparator);
    const sortedBackup = [...this.state.backupTexts].sort(comparator);

    this.setState({
      texts: sortedTexts,
      backupTexts: sortedBackup
    });
  }

  updateTypesDisplayed = (typesChosenArr) => {
    this.setState({
      typesDisplayed: typesChosenArr
    }, () => this.filterAndDisplayTypes())
  }

  // CHANGE 4C: Removed this.sort() call from filterAndDisplayTypes
  // Previously, sort() was called after every filter operation.
  // Now that backupTexts is kept sorted (see CHANGE 4B), filtering from it
  // preserves the sort order automatically - no re-sorting needed.
  filterAndDisplayTypes = () => {
    const textsCopy = this.state.backupTexts;
    const typesSet = new Set(this.state.typesDisplayed);

    // Filter texts whose type is in the selected types Set - O(n) instead of O(n*m)
    // Since backupTexts is already sorted, filteredTexts will be sorted too
    const filteredTexts = textsCopy.filter(text => typesSet.has(text.type));

    this.setState({texts: filteredTexts}, () => {
      // Re-apply search filter if there's an active search term
      if (this.state.searchTerm) {
        this.filterBySearch(this.state.searchTerm, this.state.searchField);
      }
    })
  }

  handleSearch = (searchTerm, searchField) => {
    this.setState({ searchTerm, searchField }, () => {
      if (searchTerm === '') {
        // If search is cleared, revert to type-filtered texts
        this.filterAndDisplayTypes();
      } else {
        this.filterBySearch(searchTerm, searchField);
      }
    });
  }

  filterBySearch = (searchTerm, searchField) => {
    // Normalize apostrophes/quotes (convert curly to straight) for matching
    // Uses unicode escapes: \u2018 ' \u2019 ' \u201C " \u201D "
    const normalizeQuotes = (str) => str.replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D]/g, '"');
    const searchLower = normalizeQuotes(searchTerm.toLowerCase());
    // Start from backupTexts and apply both type and search filters
    const textsCopy = this.state.backupTexts;
    const typesSet = new Set(this.state.typesDisplayed);

    // First filter by type - O(n) instead of O(n*m)
    const typeFilteredTexts = textsCopy.filter(text => typesSet.has(text.type));

    // Helper to strip HTML tags and check for match
    const stripAndMatch = (str) => {
      if (str && typeof str === 'string') {
        const plainText = str.replace(/<[^>]*>/g, '');
        return normalizeQuotes(plainText.toLowerCase()).includes(searchLower);
      }
      return false;
    };

    // Filter by search term based on selected field
    // Since typeFilteredTexts came from sorted backupTexts, result stays sorted
    const searchFilteredTexts = typeFilteredTexts.filter(text => {
      if (searchField === 'all') {
        return stripAndMatch(text.title) ||
               stripAndMatch(text.reference) ||
               stripAndMatch(text.textProvided);
      } else if (searchField === 'title') {
        return stripAndMatch(text.title);
      } else if (searchField === 'reference') {
        return stripAndMatch(text.reference);
      } else if (searchField === 'textProvided') {
        return stripAndMatch(text.textProvided);
      }
      return false;
    });

    // CHANGE 4D: Removed this.sort() call from filterBySearch
    // Previously, sort() was called after every search.
    // Now that backupTexts is kept sorted (see CHANGE 4B), the filtered
    // result is already in the correct order.
    this.setState({ texts: searchFilteredTexts });
  }

  render() {
    // While loading, render nothing (the HTML spinner overlay handles this)
    if (this.state.texts === null) {
      return null;
    }

    return (
      <div className="App">
          
          <div className="container header">
              <AboutModal/>
              <SearchBar
                onSearch={this.handleSearch}
                searchResultCount={this.state.searchTerm ? this.state.texts?.length : null}
              />
          </div>

          <div className="container main-content">
            <br/>
            <div className="row valign-wrapper">
              <div className="col l1 m2 s12">
                <b>Sort by:</b>
                </div>
              <div className="input-field col l4 m10 s12 nudge-up-on-medium-and-lower">
                <FormSelect 
                  multipleSelect={false}
                  sortByOption={this.state.sortByOption} 
                  optionNames={["Year", "Title", "Reference", "Type"]} 
                  updateSortOption={this.updateSortOption}
                  >
                </FormSelect>
              </div>
              <div className="col s12 m2 l2"><b>Types displayed:</b></div>
              <div className="col s12 m10 l5">
                <FormSelect 
                  multipleSelect={true} 
                  optionNames={["Annotation", "Blurb", "Diary", "Letter", "Poem", "Prose"]}
                  updateTypesDisplayed={this.updateTypesDisplayed}>
                </FormSelect>
              </div>
            </div>
            <div id="texts">
                {this.state.typesDisplayed.length === 0 ?
                  <div className="row center-align">
                    <br/>
                    <h5>Choose at least one type of text to display.</h5>
                  </div>
                  :
              <table>
                <thead>
                  <tr>
                    <th className="center-align" title="Year of publication"><span className="sortable-header" onClick={() => this.handleHeaderSort("year")}>Year{this.renderSortIndicator("year")}</span></th>
                    <th><span className="sortable-header" onClick={() => this.handleHeaderSort("title")}>Title{this.renderSortIndicator("title")}</span></th>
                    <th className="hide-on-small-only"><span className="sortable-header" onClick={() => this.handleHeaderSort("reference")}>Reference{this.renderSortIndicator("reference")}</span></th>
                    <th className="hide-on-med-and-down"><span className="sortable-header" onClick={() => this.handleHeaderSort("type")}>Type{this.renderSortIndicator("type")}</span></th>
                    <th></th>
                    <th className="hide-on-med-and-down"></th>
                  </tr>
                </thead>
                <tbody className="z-depth-2">
                  {this.state.texts.map((text, index) => {
                    return (
                    // CHANGE 3B: Use stable key based on content instead of array index
                    // Previously, key={index} meant that when rows were filtered or reordered,
                    // React couldn't tell which rows were the same - a row that was index 5
                    // might become index 2, causing React to rebuild it unnecessarily.
                    // Now the key is based on the text's content (year + title + reference),
                    // so React can correctly identify and reuse existing row components.
                    <TableRow
                      year={text.year}
                      title={text.title}
                      reference={text.reference}
                      type={text.type}
                      textProvided={text.textProvided}
                      notes={text.notes}
                      tooltipNotes={text.tooltipNotes}
                      key={text.id || `${text.year}-${text.title}-${text.reference}`}
                      uid={text.id || ('idx' + index)}>
                    </TableRow>
                    )
                  })}
                </tbody>
              </table>}
            </div>
          </div>

        <div className="footer">
          <Footer/>
        </div>

      </div>
    )
  };
};

export default App;
